L000471	\textit{General Expressions of $P_L(x_0)$ and $P_R(x_0)$}
L000472	\end{center}
L000473	In Eq.~\eqref{letter-neq-1}, we explained that the detection amplitudes, $\phi_n^{(L)}$ and $\phi_n^{(R)}$, are mapped to two auxiliary single-target detection amplitudes $\chi _{n}^{\left( \pm \right)}=\braket{d_{\pm} |U(\tau) \left[ \left(1-\ket{d_{\pm}} \bra{d_{\pm}} \right) U(\tau)\right]^{n-1}|x_0}$. Summing the squared moduli of the first-detection amplitudes over $n$ yields the splitting probabilities
L000474	\begin{align}
L000475	& P_L(x_0) = \sum _{n=1}^{\infty} \big| \phi_n^{(L)} \big|^2 = \frac{1}{2} \left[ \rho _+(x_0) + \rho _-(x_0) \right]+  ~\text{Re} \left[ \sum_{n=1}^{\infty} \chi _{n}^{\left( + \right)} ~\left( \chi _{n}^{\left( - \right)} \right)^* \right], \label{SI-1} \\
L000476	& P_R(x_0) = \sum _{n=1}^{\infty} \big| \phi_n^{(R)} \big|^2 = \frac{1}{2} \left[ \rho _+(x_0) + \rho _-(x_0) \right]- ~\text{Re} \left[ \sum_{n=1}^{\infty} \chi _{n}^{\left( + \right)} ~\left( \chi _{n}^{\left( - \right)} \right)^* \right]. \label{SI-2}
L000477	\end{align}
L000478	Here, $\rho _{\pm}(x_0) = \sum _{n=1}^{\infty} \big| \chi _{n}^{\left( \pm \right)}  \big|^2  $ are the total detection probabilities in the auxiliary problems. Single-target detection problems of this type have been extensively studied before \cite{QW6, QW12,QW16, QW21, QW7, QW8,QW13}. Leveraging these methods within our mapping, we
L000479	get $\rho _{\pm}(x_0) $ that appear in Eqs.~\eqref{SI-1} and \eqref{SI-2}. For the Hamiltonian in Eq.~\eqref{letter-main-eqq-1} and non-special $\tau$, i.e., $\tau$ not satisfying Eq.~\eqref{letter-res-cond}, we find \cite{SMSingh2}
L000480	\begin{align}
L000481	\rho _+(x _0) = \sum_{\substack{k=1 \\ k \in  \,\text{odd}}}^{N} \big| \braket{E_k | x _0} \big|^2,~~\rho _-(x _0) = \sum_{\substack{k=1 \\ k \in  \,\text{even}}}^{N} \big| \braket{E_k | x _0} \big|^2. \label{aux-eq-4}
L000482	\end{align}
L000483	where $\ket{E_k}$ is the energy eigenstate.
L000484	
L000485	To obtain the interference part in Eqs.~\eqref{SI-1} and \eqref{SI-2}, it is instructive to introduce the auxiliary generating functions $ \widetilde{\chi}^{(\pm)}(z) =  \sum _{n=1}^{\infty} z^n  \chi _{n}^{\left( \pm \right)}  $. Using earlier methods \cite{QW6,QW16}, we can write them as \cite{SMSingh2}
L000486	\begin{align}
L000487	\widetilde{\chi}^{(+)}(z) =\frac{\sum _{k \in ~\rm{odd}} \sin (\omega _k) \sin (\omega_k x_0 ) \left(  \frac{z e^{2 i  \tau \cos (\omega _k)}}{1-z ~e^{2 i \tau \cos (\omega _k)}}  \right)  }{ \sqrt{2}  \sum _{k \in ~\rm{odd}} \sin ^2 (\omega _k)  \left( \frac{1}{1-z ~e^{2 i \tau \cos (\omega _k)}}  \right)      },~~\widetilde{\chi}^{(-)}(z) =\frac{\sum _{k \in ~\rm{even}} \sin (\omega _k) \sin (\omega_k x_0 ) \left( \frac{ze^{2 i  \tau \cos (\omega _k)}}{1-z ~e^{2 i \tau \cos (\omega _k)}}  \right)  }{  \sqrt{2} \sum _{k \in ~\rm{even}} \sin ^2 (\omega _k)  \left( \frac{1}{1-z ~e^{2 i  \tau \cos (\omega _k)}}  \right) }, \label{SI-3}
L000488	\end{align}
L000489	where $\omega _k = \pi k/ (N+1)$. In terms of these generating functions, the interference term in Eqs.~\eqref{SI-1} and \eqref{SI-2} can be expressed as
