L000796	\section{Eigenvalues of the single-target survival operators}
L000797	\label{appen-SM-eigenvalue}
L000798	In Eq.~\eqref{supp-SR-eq-6}, we saw that the detection amplitudes $\chi_{n}^{(\pm)}$ are characterized by the survival operators
L000799	\begin{align}
L000800	\mathcal{S}_{\pm}=\Big( \mathbbm{1}-\ket{d_{\pm}} \bra{d_{\pm}}\Big) U(\tau). \label{SM-eq-ev-1}
L000801	\end{align}
L000802	The eigenspectrum of $\mathcal{S}_{\pm}$ determines the behavior of $\chi_{n}^{(\pm)}$. Here, we examine their eigenvalues for the nearest-neighbor tight-binding Hamiltonian for non-resonant sampling times, i.e., Eq.~\eqref{resonance-eqn} is not satisfied. These results are summarized in Table~\ref{tab:Spm-eigs}, and we derive them below. For simplicity, we present the derivation for $\mathcal{S}_{-}$. The same steps can be carried out for $\mathcal{S}_{+}$.
L000803	
L000804	The eigenvalues and the eigenstates of the Hamiltonian are given by
L000805	 \begin{align}
L000806	E_{k}=-2  \cos \left( \omega_k \right),~~\ket{E_k} = \sqrt{\frac{2}{N+1}}~ \sum _{x=1}^{N} ~\sin \left( \omega_k x \right)~\ket{x}, \label{SM-eq-ev-2}
L000807	\end{align}
L000808	where $\omega_k= \pi k / (N+1)$ with $k = 1,2, \ldots,N$. The target state $\ket{d_{-}} = (\ket{1}-\ket{N})/\sqrt{2}$ becomes
L000809	\begin{align}
L000810	\ket{d_{-}} =  \frac{2}{\sqrt{N+1}} \sum_{\substack{k=1 \\ k \in  \,\text{even}}}^{N} \sin \left( \frac{\pi k}{N+1} \right)~\ket{E_k}. \label{SM-eq-ev-3}
L000811	\end{align}
L000812	Let $\lambda_{-}$ denote the eigenvalue of $\mathcal{S}_-$. It satisfies the characteristic equation
L000813	\begin{align}
L000814	& \text{det}\left( \lambda_{-} \mathbbm{1} -\mathcal{S}_-  \right)=0, \\
L000815	\implies & \text{det} \left(\lambda_{-} \mathbbm{1}-U(\tau)+\ket{d_-}\bra{d_-} U(\tau)\right) = 0, \\
L000816	\implies & \text{det} \left( \lambda_- \mathbbm{1}-U(\tau) \right) \times \left( 1 + \left\langle d_- \bigg| \frac{U(\tau)}{\lambda_- \mathbbm{1}-U(\tau)} \bigg|d_- \right\rangle \right)=0.
L000817	\label{SM-eq-ev-4}
L000818	\end{align}
L000819	In the last line, we have used the matrix determinant lemma: For an invertible square matrix $A$ and column vectors $\ket{u}$ and $\ket{v}$
L000820	\begin{align}
L000821	\text{det} \left( A+\ket{u} \bra{v} \right) = \text{det}
L000822	(A) \times \left(  1 + \braket{v|A^{-1}|u}  \right). \label{SM-eq-ev-5}
L000823	\end{align}
L000824	Eq.~\eqref{SM-eq-ev-4} implies that
L000825	\begin{align}
L000826	\text{det} \left( \lambda_- \mathbbm{1}-U(\tau) \right) = 0, \quad \text{or } \left( 1 + \left\langle d_- \bigg| \frac{U(\tau)}{\lambda_- \mathbbm{1}-U(\tau)} \bigg|d_- \right\rangle \right) = 0. \label{SM-eq-ev-6}
L000827	\end{align}
L000828	The first condition yields $\lambda_- = e^{-i E_k \tau}$, i.e., the eigenvalues of $U(\tau)$. From Eq.~\eqref{SM-eq-ev-1}, we see that such a solution occurs only if the corresponding eigenmode of $U(\tau)$ is orthogonal to the $\ket{d_-}$. Eq.~\eqref{SM-eq-ev-3} tells us that $\braket{E_k|d_-} = 0$ if $k$ is odd. This means that
L000829	\begin{align}
L000830	\lambda_- = \{ e^{-iE_k \tau}\}, \quad \text{where } k \text{ is odd}. \label{SM-eq-ev-7}
L000831	\end{align}
L000832	These account for $N/2$ eigenvalues of $\mathcal{S}_-$ when $N$ is even, and $(N+1)/2$ eigenvalues when $N$ is odd. The remaining eigenvalues follow from the second condition in Eq.~\eqref{SM-eq-ev-6}
L000833	\begin{align}
L000834	\lambda_- \left\langle d_- \bigg| \frac{ \mathbbm{1}}{\lambda_- \mathbbm{1}-U(\tau)} \bigg|d_- \right\rangle = 0. \label{SM-eq-ev-8}
L000835	\end{align}
L000836	The trivial solution is
L000837	\begin{align}
L000838	\lambda_- = 0. \label{SM-eq-ev-99}
L000839	\end{align}
L000840	Other solutions are
L000841	\begin{align}
L000842	& \left\langle d_- \bigg| \frac{ \mathbbm{1}}{\lambda_- \mathbbm{1}-U(\tau)} \bigg|d_- \right\rangle = 0,
L000843	\implies   \sum_{\substack{k=1 \\ k \in  \,\text{even}}}^{N} \frac{\sin^2 (\omega _k) }{\left( \lambda_-- ~e^{2 i  \tau \cos (\omega _k) } \right)}   =0, \label{SM-eq-ev-9}
L000844	\end{align}
L000845	where $\omega_k = \pi k /(N+1)$. Eq.~\eqref{SM-eq-ev-9} can be interpreted in the language of the classical charge theory \cite{QW21, QW13}. The points $e^{2 i \tau \cos(\omega_k)}$ (for even $k$) lie on the unit circle and act as sources with positive weights $\sin^2(\omega_k)$, while Eq.~\eqref{SM-eq-ev-9} is precisely the requirement that the net force field vanishes at $\lambda_-$, i.e., $\lambda_-$ is an equilibrium point of the forces generated by these charges. Solving Eq.~\eqref{SM-eq-ev-9} generates the $(N/2-1)$ eigenvalues of $\mathcal{S}_-$ for even $N$ and $(N-3)/2$ for odd $N$ located in the unit disc ($|\lambda _-| <1$).
L000846	
L000847	
L000848	To sum up, Eqs.~(\ref{SM-eq-ev-7}, \ref{SM-eq-ev-99}, \ref{SM-eq-ev-9}) give the $N$ eigenvalues of the $\mathcal{S}_-$ operator. These results are summarized in Table~\ref{tab:Spm-eigs}, which also lists the eigenvalues of $\mathcal{S}_+$.
