L000904	\section{Relation of the splitting probability with the eigenvalues of the survival operator}
L000905	\label{sec-SM-relation}
L000906	In the Letter, we pointed out that the interference term $\xi(x_0,N,\tau)$ admits two equivalent spectral expansions, one in terms of the eigenvalues $\{ \lambda_-\}$ of the survival operator $\mathcal{S}_-$ and the other in terms of $\{ \lambda_+\}$ of $\mathcal{S}_+$. Here, we derive both expansions.
L000907	\subsection{$\xi(x_0,N,\tau)$ as an expansion in $\{ \lambda_-\}$}
L000908	Recall that the splitting probabilities are given by
L000909	\begin{align}
L000910	P_L(x _0) = \frac{1}{2}+ \xi (x _0, N, \tau),~~~ P_R(x _0) = \frac{1}{2}-\xi (x _0, N, \tau), \label{supp-letter-neq-2}
L000911	\end{align}
L000912	where the term $\xi(x_0, N, \tau)$ is given in terms of the generating functions $\widetilde{\chi}^{(\pm)}(z) $ in Eq.~\eqref{SP-SR-eq-6}. By contrast, using the other yet equivalent expression of $\xi(x_0, N, \tau)$ in Eq.~\eqref{SP-SR-eq-6-nn}, we yield a different expansion, as shown later.
L000913	
L000914	
L000915	The generating functions are given in Eq.~\eqref{SI-3j81}, and plugging them in Eq.~\eqref{SP-SR-eq-6} gives
L000916	\begin{align}
L000917	& \xi(x_0, N, \tau) = \text{Re} \left[ \oint_{|z|=1} dz~\mathcal{I}(z, x_0,N,\tau) \right], ~~\text{with} \label{supp-SI-4}\\
L000918	& \mathcal{I}(z,x_0,N, \tau) = \frac{1}{4 \pi  i z}  \left[ \frac{\sum _{k \in ~\rm{even}} \sin (\omega _k) \sin (\omega_k x_0 ) \left( \frac{e^{-2 i  \tau \cos (\omega _k)}}{z- ~e^{-2 i  \tau \cos (\omega _k)}}  \right)  }{   \sum _{k \in ~\rm{even}} \sin^2 (\omega _k)  \left( \frac{1}{z- ~e^{-2 i  \tau \cos (\omega _k)}}  \right)      } \right] \left[ \frac{\sum _{k \in ~\rm{odd}} \sin (\omega _k) \sin (\omega_k x_0 ) \left( \frac{e^{2 i  \tau \cos (\omega _k)}}{1-z ~e^{2 i \tau \cos (\omega _k)}}  \right)  }{   \sum _{k \in ~\rm{odd}} \sin ^2 (\omega _k)  \left( \frac{1}{1-z ~e^{2 i  \tau \cos (\omega _k)}}  \right)      } \right] , \label{supp-pole-eq-2}
L000919	\end{align}
L000920	where $\omega _k = \pi k /(N+1)$. Eq.~\eqref{supp-SI-4} indicates the contour integration of a complex function $\mathcal{I}(z, x_0, N, \tau)$ over a unit circle. By the residue theorem, this integral can be evaluated as the sum of the residues of $\mathcal{I}(z,x_0,N,\tau)$ at its singularities inside the contour. Let us analyze its singularities.
L000921	
L000922	A numerical inspection of Eq.~\eqref{supp-pole-eq-2} reveals that the only singularities present are simple poles. The first pole is $z_{\rm pole}=0$. Other poles are obtained by solving
L000923	\begin{align}
L000924	& \sum _{k \in ~\rm{even}} \sin^2 (\omega _k)  \left( \frac{1}{z_{\rm pole}- ~e^{-2 i  \tau \cos (\omega _k)}}  \right)  = 0, \label{suppSR-eq-pole-1} \\
L000925	&  \sum _{k \in ~\rm{odd}} \sin ^2 (\omega _k)  \left( \frac{1}{1-z_{\rm pole} ~e^{2 i  \tau \cos (\omega _k)}}  \right) =0. \label{suppSR-eq-pole-2}
L000926	\end{align}
L000927	Comparing Eq.~\eqref{suppSR-eq-pole-1} with the eigenvalue condition for $\mathcal{S}_-$ in Table~\ref{tab:Spm-eigs}, we identify $z_{\rm pole}=\lambda_-^{*}$ (where ${}^*$ denotes complex conjugation). In particular, Eq.~\eqref{suppSR-eq-pole-1} corresponds to the nontrivial eigenvalues of $\mathcal{S}_-$, which satisfy $0<|\lambda_-|<1$. Hence $0<|z_{\rm pole}|<1$, so these poles lie inside the unit disk and contribute to the contour integral in Eq.~\eqref{supp-SI-4}.
L000928	
L000929	Similarly, comparing Eq.~\eqref{suppSR-eq-pole-2} with Table~\ref{tab:Spm-eigs}, we find that these poles are related to the eigenvalues of $\mathcal{S}_+$ via $z_{\rm pole}=1/\lambda_{+}$. Since Eq.~\eqref{suppSR-eq-pole-2} corresponds to the nontrivial eigenvalues of $\mathcal{S}_+$, which satisfy $0<|\lambda_+|<1$, it follows that $|z_{\rm pole}|=|1/\lambda_+|>1$. Hence these poles lie outside the unit disc and do not contribute to the contour integral in Eq.~\eqref{supp-SI-4}.
L000930	
L000931	Therefore, $\xi(x_0,N,\tau)$ in this particular representation is determined solely by the poles $z_{\rm pole}=\lambda_-^{*}$ corresponding to the  eigenvalues of $\mathcal{S}_-$ with $|\lambda_-|<1$ (including $\lambda_-=0$)
L000932	\begin{align}
L000933	\xi(x_0,N, \tau) = -2 \pi~   \sum_{ |\lambda_-|<1} \text{Im} \left[ \operatorname{Residue}\!\left[\mathcal{I};\, z=\lambda_-^*\right] \right], \label{pole-eq-4}
L000934	\end{align}
L000935	where $\operatorname{Residue}\!\left[\mathcal{I};\, z=\lambda_-^*\right]$ denotes the residue of the function $\mathcal{I}( z, x_0,N,\tau)$ at the pole $z=\lambda_-^*$. This relation makes explicit that $\xi(x_0,N,\tau)$ can be written as a summed contribution of the eigenvalues $\{\lambda_-\}$.
L000936	
L000937	{\color{black}
L000938	\subsection{$\xi(x_0,N,\tau)$ as an expansion in $\{ \lambda_+\}$}
L000939	We now show that $\xi(x_0,N,\tau)$ can also be written as a summed contribution of the eigenvalues $\{\lambda_+\}$ of the survival operator $\mathcal{S}_+$. To show this, we begin with $\xi(x_0,N,\tau)$ in Eq.~\eqref{SP-SR-eq-6-nn} and rewrite it as
L000940	\begin{align}
L000941	& \xi(x_0, N, \tau) = \text{Re} \left[ \oint_{|z|=1} dz~\mathcal{J}(z, x_0,N,\tau) \right], ~~\text{with} \label{supp-SI-4-pssrk}\\
L000942	& \mathcal{J}(z,x_0,N, \tau) = \frac{1}{4 \pi  i z}  \left[ \frac{\sum _{k \in ~\rm{odd}} \sin (\omega _k) \sin (\omega_k x_0 ) \left( \frac{e^{-2 i  \tau \cos (\omega _k)}}{z- ~e^{-2 i  \tau \cos (\omega _k)}}  \right)  }{   \sum _{k \in ~\rm{odd}} \sin^2 (\omega _k)  \left( \frac{1}{z- ~e^{-2 i  \tau \cos (\omega _k)}}  \right)      } \right] \left[ \frac{\sum _{k \in ~\rm{even}} \sin (\omega _k) \sin (\omega_k x_0 ) \left( \frac{e^{2 i  \tau \cos (\omega _k)}}{1-z ~e^{2 i \tau \cos (\omega _k)}}  \right)  }{   \sum _{k \in ~\rm{even}} \sin ^2 (\omega _k)  \left( \frac{1}{1-z ~e^{2 i  \tau \cos (\omega _k)}}  \right)      } \right] , \label{supp-pole-eq-2-pssrk}
L000943	\end{align}
L000944	With this form, one can perform the same analysis as before to show that the only contributing poles to Eq.~\eqref{supp-SI-4-pssrk} are $z_{\rm pole} = \lambda_+^*$, while the other poles $z_{\rm pole} = 1/\lambda_-$ do not contribute. Following the same steps as before, we then obtain
L000945	\begin{align}
L000946	\xi(x_0,N, \tau) = -2 \pi~   \sum_{ |\lambda_+|<1} \text{Im} \left[ \operatorname{Residue}\!\left[\mathcal{J};\, z=\lambda_+^*\right] \right], \label{pole-eq-4-PSSRk}
L000947	\end{align}
L000948	Thus in this representation, only the $\{ \lambda_+ \}$ eigenvalues contribute to $\xi(x_0,N, \tau)$ and hence control the splitting probability.}
